const pass=window.localStorage.getItem("pass");function enviarPass(){document.getElementById("enviar").removeEventListener("click",enviarPass);let e=document.getElementById("pass").value;window.localStorage.setItem("pass",e)}pass?(document.getElementById("menu-container").style.visibility="visible",document.getElementById("login-container").style.display="none"):(document.getElementById("login-container").style.visibility="visible",document.getElementById("menu-container").style.display="none",document.getElementById("enviar").addEventListener("click",enviarPass));